(() => {
 const caption=document.querySelector('.caption'),legacy=caption.querySelector('.caption-bubbles');legacy.hidden=true;
 const list=document.createElement('div');list.id='conversationLog';list.className='conversation-log';list.setAttribute('role','log');list.setAttribute('aria-label','Histórico da conversa');list.setAttribute('aria-live','polite');list.setAttribute('aria-relevant','additions text');
 const empty=document.createElement('p');empty.className='conversation-empty';empty.textContent='As falas da professora e do aluno aparecem aqui, na ordem da conversa.';list.append(empty);caption.append(list);
 const actions=document.createElement('div');actions.id='conversationHistoryActions';caption.querySelector('.caption-heading').after(actions);
 const voice=document.createElement('p');voice.id='conversationVoiceStatus';voice.setAttribute('role','status');voice.hidden=true;actions.after(voice);const media=document.getElementById('mediaStatus');const showVoice=()=>{voice.textContent=media.textContent;voice.hidden=!voice.textContent;};new MutationObserver(showVoice).observe(media,{childList:true,subtree:true,characterData:true});showVoice();
 const newer=document.createElement('button');newer.id='conversationLatest';newer.type='button';newer.textContent='Novas mensagens ↓';newer.hidden=true;caption.append(newer);
 let follow=true;const entries=new Map(),drafts=new Map();let sequence=0;
 list.addEventListener('scroll',()=>{follow=list.scrollHeight-list.clientHeight-list.scrollTop<55;if(follow)newer.hidden=true;});newer.onclick=()=>{follow=true;list.scrollTop=list.scrollHeight;newer.hidden=true;};
 function key(data){return data.memberId+':'+(data.clientId||data.id)}
 function node(role,name){const article=document.createElement('article');article.className='conversation-message '+(role==='teacher'?'from-teacher':'from-student');const head=document.createElement('div');head.className='conversation-author';const title=document.createElement('strong');title.dataset.userContent='true';const badge=document.createElement('span');badge.className='conversation-role';badge.textContent=role==='teacher'?'Professora':'Aluno';const time=document.createElement('time');head.append(title,badge,time);const text=document.createElement('p'),original=document.createElement('p'),status=document.createElement('small');text.className='conversation-primary';original.className='conversation-original';text.dataset.userContent=original.dataset.userContent='true';article.append(head,text,original,status);title.textContent=name;return {article,title,time,text,original,status};}
 function paint(n,{text,original,status,at,primaryLanguage,secondaryLanguage}){n.text.textContent=text||'';n.text.lang=primaryLanguage||'';n.original.textContent=original&&original!==text?original:'';n.original.lang=secondaryLanguage||'';n.original.hidden=!n.original.textContent;n.status.textContent=status||'';n.status.hidden=!status;if(at){n.time.dateTime=at;n.time.textContent=new Date(at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}}
 function scroll(){empty.hidden=entries.size>0||drafts.size>0;if(follow){list.scrollTop=list.scrollHeight;newer.hidden=true;}else newer.hidden=false;}
 function confirmed(memberId,turnId){for(const [id,d]of drafts)if(d.memberId===memberId&&(!turnId||d.turnId===turnId)){d.article.remove();drafts.delete(id);}}
 function record(data,role,display){const anchor=!follow?[...list.children].find(e=>e.getBoundingClientRect().bottom>list.getBoundingClientRect().top):null,anchorTop=anchor?.getBoundingClientRect().top;const id=key(data);let n=entries.get(id);if(!n){n={...node(role,data.name),at:data.at,order:++sequence};entries.set(id,n);const next=[...entries.values()].filter(e=>e!==n).sort((a,b)=>new Date(a.at)-new Date(b.at)||a.order-b.order).find(e=>new Date(e.at)>new Date(n.at));list.insertBefore(n.article,next?.article||[...drafts.values()][0]?.article||null);}n.article.classList.toggle('conversation-gap',data.kind==='gap');n.title.textContent=data.name;paint(n,{...display,at:data.at});if(data.liveTurnId)confirmed(data.memberId,data.liveTurnId);if(anchor?.isConnected&&!follow)list.scrollTop+=anchor.getBoundingClientRect().top-anchorTop;scroll();}
 function preview(member,draft,display){const id=member.id+':'+draft.turnId;let n=drafts.get(id);if(!n){confirmed(member.id);n={...node(member.role,member.name),memberId:member.id,turnId:draft.turnId};n.article.classList.add('conversation-provisional');drafts.set(id,n);list.append(n.article);}paint(n,display);scroll();}
 window.conversationUI={record,preview,confirmed,removePreview:member=>{confirmed(member.id);scroll();}};
})();
